"""Baseline policy with a one-step reward-aware tie breaker."""

from __future__ import annotations

from typing import Any

from policies.heuristic_baseline import choose_actions as _baseline_choose


def choose_actions(
    *,
    observation_text: str,
    session: dict[str, Any],
    valid_actions: list[str],
    engine: Any = None,
    readout: dict[str, Any],
    seed: int,
    ply: int,
) -> dict[str, Any]:
    decision = _baseline_choose(
        observation_text=observation_text,
        session=session,
        valid_actions=valid_actions,
        engine=engine,
        readout=readout,
        seed=seed,
        ply=ply,
    )
    if engine is None:
        return decision
    chosen = decision.get("actions", [None])[0]
    candidates = [action for action in valid_actions if action != "noop"]
    best_action = chosen
    best_reward = _step_reward(engine, chosen)
    for action in candidates:
        reward = _step_reward(engine, action)
        if reward > best_reward:
            best_action, best_reward = action, reward
    if best_action and best_action != chosen:
        return {"actions": [best_action], "policy_reason": "take higher immediate reward"}
    return decision


def _step_reward(engine: Any, action: Any) -> float:
    if not action:
        return float("-inf")
    sim = engine.clone_for_sim()
    before_invalid = sim.private.invalid_action_count
    sim.step(action)
    if sim.private.invalid_action_count > before_invalid:
        return float("-inf")
    return float(sim.private.reward_last)

