"""Craftax heuristic with the symbolic crafting-table marker corrected."""

from __future__ import annotations

from typing import Any

from policies.heuristic_baseline import (
    _nearby,
    _route_to_adjacent,
    choose_actions as _baseline_choose,
)


def choose_actions(
    *,
    observation_text: str,
    session: dict[str, Any],
    valid_actions: list[str],
    engine: Any = None,
    readout: dict[str, Any],
    seed: int,
    ply: int,
) -> dict[str, Any]:
    obs = readout["observation"]
    inv = obs["inventory"]
    table_near = _nearby(obs["local_map"], "Z")
    if inv.get("pickaxe", 0) < 1:
        if table_near and inv.get("wood", 0) >= 1 and "make_wood_pickaxe" in valid_actions:
            return {"actions": ["make_wood_pickaxe"], "policy_reason": "craft wood pickaxe at table"}
        if "place_table" in obs.get("achievements", []) and not table_near:
            route = _route_to_adjacent(
                str(readout.get("ascii", "")).splitlines(),
                tuple(inv_pos for inv_pos in obs["player"]["pos"]),
                "Z",
            )
            for action in route:
                if action in valid_actions:
                    return {"actions": [action], "policy_reason": "return to crafting table"}
    return _baseline_choose(
        observation_text=observation_text,
        session=session,
        valid_actions=valid_actions,
        engine=engine,
        readout=readout,
        seed=seed,
        ply=ply,
    )

